// ==============================================================================
// PLAIN-ENGLISH GUIDE
//
// WHAT THIS FILE IS: loads the recipes that come with the app from
// assets/recipes.json (a text file inside the app). That file is generated by
// tools/recipes/generate_recipes.py, so edit the Python data, not the JSON.
// ==============================================================================
package com.gymnam.app.data

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import org.json.JSONObject

/** The built-in recipes from assets/recipes.json (made by tools/recipes/generate_recipes.py). */
class BuiltInRecipes(private val context: Context) {
    // mutex = a "one at a time" lock, so two screens don't read the file at the same time.
    // cache = the recipes we already read, so the file is read only once
    // (re-read only if you switch between English and Spanish).
    private val mutex = Mutex()
    private var cache: Pair<Boolean, List<RecipeModel>>? = null

    // Reads the JSON file and turns each recipe into a RecipeModel the screens
    // understand. Dispatchers.IO = do the file reading on a background worker.
    suspend fun all(spanish: Boolean): List<RecipeModel> = mutex.withLock {
        cache?.takeIf { it.first == spanish }?.second ?: withContext(Dispatchers.IO) {
            val text = context.assets.open("recipes.json").bufferedReader(Charsets.UTF_8).use { it.readText() }
            val arr = JSONObject(text).getJSONArray("recipes")
            (0 until arr.length()).map { i ->
                val o = arr.getJSONObject(i)
                val ings = o.getJSONArray("ingredients").let { a ->
                    (0 until a.length()).map { Ingredient.fromJson(a.getJSONObject(it), spanish) }
                }
                val steps = o.getJSONArray(if (spanish) "steps_es" else "steps_en").let { a ->
                    (0 until a.length()).map { a.getString(it) }
                }
                RecipeModel(
                    key = "builtin:${o.getString("id")}",
                    name = o.getString(if (spanish) "es" else "en"),
                    emoji = o.optString("emoji", "🍽️"),
                    servings = o.getInt("servings"), minutes = o.optInt("minutes", 0),
                    kcal = o.getDouble("kcal"), proteinG = o.getDouble("p"),
                    carbsG = o.getDouble("c"), fatG = o.getDouble("f"),
                    ingredients = ings, steps = steps, source = RecipeSource.BUILTIN
                )
            }
        }.also { cache = spanish to it }
    }
}
